// Validate the whole writable tree before reading any generated bytes. Run the
// comparison in a separate read-only capability after generators have exited.
import { constants, closeSync, fstatSync, lstatSync, openSync, readFileSync, readdirSync, realpathSync } from "node:fs";
import { createHash } from "node:crypto";
import path from "node:path";
import { pathToFileURL } from "node:url";

function relative(file) {
  if (typeof file !== "string" || !file || path.isAbsolute(file) || file.split(/[\\/]/u).some(part => !part || part === "." || part === "..")) throw new Error(`invalid generation path: ${file}`);
  return file;
}
function directory(file) {
  if (!lstatSync(file).isDirectory() || realpathSync(file) !== path.resolve(file)) throw new Error(`linked or non-directory generation path: ${file}`);
}
function regular(root, file, singleLink = true) {
  relative(file);
  let parent = root;
  directory(parent);
  for (const part of file.split("/").slice(0, -1)) { parent = path.join(parent, part); directory(parent); }
  const target = path.join(root, file), info = lstatSync(target);
  if (!info.isFile() || (singleLink && info.nlink !== 1)) throw new Error(`linked or nonregular generation file: ${file}`);
  return info;
}
function readRegular(root, file, singleLink = true) {
  const before = regular(root, file, singleLink);
  const fd = openSync(path.join(root, file), constants.O_RDONLY | constants.O_NOFOLLOW | constants.O_NONBLOCK);
  try {
    const after = fstatSync(fd);
    if (!after.isFile() || (singleLink && after.nlink !== 1) || after.dev !== before.dev || after.ino !== before.ino) throw new Error(`generation file changed while opening: ${file}`);
    return readFileSync(fd);
  } finally { closeSync(fd); }
}
export function validateGenerationOutputs(source, baseline, {inputs, outputs, output_directories: roots}) {
  source = path.resolve(source); baseline = path.resolve(baseline);
  const expected = new Set([...inputs, ...outputs].map(relative));
  const directories = new Set();
  roots.forEach(relative);
  for (const output of outputs) if (!roots.some(root => output.startsWith(root + "/"))) throw new Error(`output outside declared generation directories: ${output}`);
  for (const file of expected) {
    let parent = path.dirname(file);
    while (parent !== ".") { directories.add(parent); parent = path.dirname(parent); }
  }
  const visit = file => {
    const target = path.join(source, file), info = lstatSync(target);
    if (info.isDirectory()) {
      if (!directories.has(file)) throw new Error(`undeclared generation directory: ${file}`);
      directory(target);
      for (const name of readdirSync(target).sort()) visit(`${file}/${name}`);
    } else {
      if (!expected.has(file)) throw new Error(`undeclared generation output: ${file}`);
      regular(source, file);
    }
  };
  // Complete inventory and every parent are checked before content reads begin.
  roots.forEach(visit);
  for (const file of expected) regular(source, file);
  const hashes = {};
  for (const file of [...expected].sort()) {
    const actual = readRegular(source, file);
    // Reference files may be hard-linked from the immutable build cache. Only
    // the private produced tree must prove that it has no external inode alias.
    if (!actual.equals(readRegular(baseline, file, false))) throw new Error(`isolated generation content mismatch: ${file}`);
    if (outputs.includes(file)) hashes[file] = createHash("sha256").update(actual).digest("hex");
  }
  return hashes;
}
if (process.argv[1] && import.meta.url === pathToFileURL(realpathSync(process.argv[1])).href) {
  const [source, baseline, manifest] = process.argv.slice(2);
  if (!manifest) throw new Error("explicit generation output inventory required");
  process.stdout.write(JSON.stringify(validateGenerationOutputs(source, baseline, JSON.parse(readFileSync(manifest)))));
}
